/* eslint-disable no-undef */
import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

@Component({
  tag: 'groupui-breadcrumbs',
  styleUrl: 'breadcrumbs.scss',
  shadow: true,
})
export class Breadcrumbs implements ComponentInterface {
  /**
   * defines the maximum number of breadcrumb items before the breadcrumbs collapse
   */
  @Prop({ reflect: true }) readonly maxItems: number = 5;

  /**
   * defines the breakpoint in pixels under which the breadcrumbs expand into a dropdown menu
   */
  @Prop({ reflect: true }) readonly breakpoint: number = 960;

  @State() manuallyExpanded: boolean = false;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  private placeholder: HTMLGroupuiBreadcrumbElement;
  private dropdown: HTMLGroupuiBreadcrumbDropdownElement;

  private ariaAttributes: AriaAttributes;

  @Listen('focusout')
  onBlur(event: FocusEvent) {
    if (this.manuallyExpanded && this.isOutsidePlaceholder(event)) {
      this.closeDropdown();
    }
  }

  @Listen('keydown')
  async onKeydown(event: KeyboardEvent) {
    if (event.key === 'Escape' && this.manuallyExpanded) {
      this.closeDropdown();
      this.fixRefocus();
    }
  }

  @Watch('maxItems')
  onMaxItemsChange() {
    this.resetBreadcrumbs();
  }

  private resetBreadcrumbs() {
    if (this.getElements().length < 3 || this.elementsWouldFit()) {
      this.moveElementsOutOfDropdown();
      this.removePlaceholder();
      this.expandElements();
    }
  }

  private elementsWouldFit() {
    const isPlaceholderVisible = this.placeholder.hasChildNodes() ? 1 : 0;
    return this.getElements().length <= this.maxItems + isPlaceholderVisible;
  }

  private fixRefocus() {
    requestAnimationFrame(() => {
      this.placeholder.focus();
    });
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.placeholder = this.createPlaceholder();
    this.dropdown = Breadcrumbs.createDropdown();
  }

  componentWillRender() {
    this.updateExpanded();
  }

  componentDidRender() {
    this.makeLastElementNotFocusable();
    this.setAriaLabelOfLastElement();
    this.setLastElementProperty();
  }

  private closeDropdown() {
    this.moveElementsOutOfDropdown();
    this.dropdown.remove();
    this.manuallyExpanded = false;
  }

  private getElements(): HTMLGroupuiBreadcrumbElement[] {
    return Array.from(this.host.querySelectorAll('groupui-breadcrumb'));
  }

  private makeLastElementNotFocusable() {
    if (this.getElements().length === 0) return;

    for (const element of this.getElements()) {
      element.tabIndex = 0;
    }
    this.lastElement().tabIndex = -1;
  }

  private setAriaLabelOfLastElement() {
    for (const element of this.getElements()) {
      element.removeAttribute('aria-current');
    }
    if (this.getElements().length > 0) {
      this.lastElement().setAttribute('aria-current', 'page');
    }
  }

  private setLastElementProperty() {
    for (const element of this.getElements()) {
      element.last = false;
    }
    if (this.getElements().length > 0) {
      this.lastElement().last = true;
    }
  }

  private updateExpanded() {
    if (this.manuallyExpanded) {
      this.showCollapsedElements();
      return;
    }
    if (this.getElements().length < 3 || this.getElements().length <= this.maxItems) return;
    this.hideCollapsedElements();
    this.dropdown.remove();
    this.insertPlaceholder();
  }

  private showCollapsedElements() {
    if (window.innerWidth >= this.breakpoint) {
      this.moveElementsOutOfDropdown();
      this.removePlaceholder();
    } else {
      this.showElementsInDropdown();
    }
    this.expandElements();
  }

  private moveElementsOutOfDropdown() {
    this.getElements().forEach((element) => {
      element.inDropdown = false;
      this.host.appendChild(element);
    });
  }

  private showElementsInDropdown() {
    this.getElementsInBetween().forEach((element) => {
      element.inDropdown = true;
      this.dropdown.appendChild(element);
    });
    this.placeholder.appendChild(this.dropdown);
  }

  private isOutsidePlaceholder(event: FocusEvent) {
    return !this.placeholder.contains(event.relatedTarget as HTMLElement | null);
  }

  private expandElements() {
    this.getElements().forEach((element) => element.removeAttribute('style'));
  }

  private insertPlaceholder() {
    this.host.insertBefore(this.placeholder, this.lastElement());
  }

  private removePlaceholder() {
    this.placeholder.remove();
  }

  private hideCollapsedElements() {
    this.getElementsInBetween().forEach((element) => (element.style.display = 'none'));
  }

  private getElementsInBetween() {
    return this.getElements().filter((element, index) => {
      return index > 0 && index < this.getElements().length - 1 && element !== this.placeholder;
    });
  }

  private static createDropdown() {
    const dropdown = document.createElement('groupui-breadcrumb-dropdown');
    dropdown.slot = 'dropdown';
    return dropdown;
  }

  private createPlaceholder() {
    const placeHolder = document.createElement('groupui-breadcrumb');
    placeHolder.textContent = '...';
    placeHolder.componentOnReady &&
      placeHolder.componentOnReady().then(() => {
        placeHolder.shadowRoot.querySelector('a').onclick = () => {
          this.manuallyExpanded = !this.manuallyExpanded;
          this.fixRefocus();
        };
      });
    return placeHolder;
  }

  private onBreadcrumbsChanged() {
    this.makeLastElementNotFocusable();
    this.setAriaLabelOfLastElement();
    this.setLastElementProperty();
  }

  private lastElement() {
    if (this.getElements().length > 0) {
      return this.getElements()[this.getElements().length - 1];
    }
    return null;
  }

  render() {
    return (
      <Host>
        <nav {...this.ariaAttributes}>
          <slot onSlotchange={() => this.onBreadcrumbsChanged()} />
        </nav>
      </Host>
    );
  }
}
